/* ---------- the 90-day plan ---------- */
const TYPES={A:["t_fb_a",["squat","pushup","bridge","plank"]],B:["t_fb_b",["lunge","row","birddog","climber"]],C:["t_fb_c",["squat","pushup","row","bridge","plank"]],
UA:["t_up_a",["bench","ohp","row","tri","plank"]],LA:["t_lo_a",["gsquat","rdl","lunge","bridge"]],UB:["t_up_b",["pushup","raise","pullover","curl","deadbug"]],LB:["t_lo_b",["gsquat","lunge","rdl","bridge","climber"]],
PUSH:["t_push",["bench","incline","cablefly","ohp","raise","tri"]],PULL:["t_pull",["row","pullover","curl","deadbug","plank"]],LEGS:["t_legs",["gsquat","rdl","lunge","bridge"]],UP:["t_up",["pushup","row","ohp","pullover","curl","tri"]],LO:["t_lo",["gsquat","lunge","bridge","climber","plank","deadbug"]],
WALK:["t_walk",["walk","stretch"]],CORE:["t_core",["birddog","deadbug","climber","plank"]]};
const PAT=[["A","WALK","B","CORE","C","WALK"],["UA","LA","WALK","UB","LB","CORE"],["PUSH","PULL","LEGS","WALK","UP","LO"]];
const FOCUS_EXTRA=[null,"curl","pushup","deadbug","lunge"];

const backBtn=(act)=>`<button class="back-btn" data-a="${act}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5M12 19l-7-7 7-7"/></svg><span>${t("back")}</span></button>`;
function triggerDownload(filename, text) {
 const blob = new Blob([text], {type: "text/plain;charset=utf-8"});
 const url = URL.createObjectURL(blob);
 const a = document.createElement("a");
 a.href = url; a.download = filename;
 document.body.appendChild(a); a.click();
 setTimeout(()=>{ document.body.removeChild(a); URL.revokeObjectURL(url); }, 250);
}
function triggerShare(title, text) {
 if (navigator.share) {
  navigator.share({title: title, text: text}).catch(()=>{});
 } else if (navigator.clipboard && navigator.clipboard.writeText) {
  navigator.clipboard.writeText(text).then(()=>{ alert(t("copied_txt")); }).catch(()=>{});
 } else {
  alert(text);
 }
}

function adjFor(d){let v=0;Object.keys(S.adjAt||{}).map(Number).sort((a,b)=>a-b).forEach(k=>{if(k<d)v=S.adjAt[k]});return v}
const month=d=>d<=28?1:d<=56?2:3, week=d=>Math.ceil(d/7);
function dayPlan(d,p){
 const i=(d-1)%7,m=month(d),w=week(d);
 if(i===6)return{rest:true,w,m};
 const key=PAT[m-1][i],T=TYPES[key],lightWeek=w%4===0,walk=key==="WALK",core=key==="CORE";
 let ids=T[1].slice();
 const ex=FOCUS_EXTRA[p.focus];
 if(ex&&!walk&&!core&&!ids.includes(ex))ids.push(ex);
 if(S.lowImp)ids=ids.map(id=>id==="climber"?"birddog":id==="lunge"?"bridge":id);
 if(p.eq===2)ids=ids.map(id=>id==="row"?"cablerow":id==="gsquat"?"legpress":(id==="pushup"&&m>=2)?"incline":id);
 let s=[2,3,4][m-1],r=m===3?8:10;
 if(lightWeek){s=Math.max(2,s-1);if(m===1)r=8}
 const adj=adjFor(d);r=Math.max(6,Math.min(20,Math.min(15,r+p.lvl*2)+adj*2));
 const list=ids.map(id=>{
  if(id==="walk")return[id,1,25,"m"];
  if(id==="stretch")return[id,1,5,"m"];
  if(id==="plank"||id==="climber")return[id,core?2:s,Math.max(15,Math.round((Math.min(60,20+w*3+p.lvl*5)-(lightWeek?10:0)+adj*5)/5)*5),"s"];
  if(core)return[id,2,id==="plank"?25:8,""];
  return[id,s,r,""];
 });
 const mins=walk?30:core?15:5+list.length*6;
 return{rest:false,key,title:T[0],list,light:lightWeek,w,m,mins};
}
