const LU=[["daal","roti2","sabzi","salad"],["paneer","roti2","curd"],["daal","rice","sabzi","salad"],["paneer","roti2","salad"],["daal","roti2","sabzi","curd"],["paneer","roti1","rice","salad"],["daal","roti2","sabzi","salad"]];
