const winterOn=()=>S.winter===null||S.winter===undefined?[10,11,0,1].includes(new Date().getMonth()):S.winter;
function menuFor(d){const i=(d-1)%7,m=month(d),rest=i===6,B=["daliya","chane","almonds","makhana"];if(m===2)B.push("curd");if(m===3)B.push("milk");
 let L=LU[i].slice();if(winterOn()&&[1,3,5].includes(i))L=["saag","makki","curd","gur"];
 const Sn=[i%2?"makhana":"fruit"];if(m>=2&&!rest)Sn.push("sprouts");const D=DI[i].slice();if(m===3&&!D.includes("curd"))D.push("curd");
 const out=[["mb",B],["ml",L],["ms",Sn]];if(!rest)out.push(["mp",[i%2?"lassi":"milk"]]);out.push(["md",D]);return out}
