const KC={daliya:150,chane:70,almonds:35,makhana:40,daal:150,roti2:200,roti1:100,paneer:250,sabzi:100,salad:40,curd:90,rice:100,lassi:150,milk:150,fruit:70,saag:150,makki:150,gur:40,sprouts:100};
const ACT=[1.2,1.375,1.55];
function calcNow(){const g=id=>document.getElementById(id),a=+g("c_age").value,h=+g("c_h").value,w=+String(g("c_w").value).replace(",","."),sex=+g("c_sex").value,act=+g("c_act").value;
 if(!(a>=1&&a<=90&&h>=120&&h<=220&&w>=30&&w<=200)){alert(t("c_bad"));return false}
 S.cp={age:a,sex,h,w,act,res:null};if(a<18){S.cp.res={young:true};return true}
 const bmr=10*w+6.25*h-5*a+(sex===0?5:-161),floor=sex===0?1500:1200,goal=S.p.goal||0;
 let kc=bmr*ACT[act]+(goal===0?-400:goal===1?300:0);kc=Math.round(Math.max(floor,kc)/10)*10;
 const lo=goal===2?1.2:1.6,hi=goal===2?1.6:2.0;S.cp.res={kc,pa:Math.round(w*lo),pb:Math.round(w*hi),floor};return true}
const shortF=k=>k.indexOf("roti")===0?FD[k][S.lang]:FD[k][S.lang].replace(/ \(.*\)/,"");
function vCal(){
 const c=S.cp,r=c.res,dt=todayStr(),log=S.cal[dt]||[],eaten=log.reduce((n,x)=>n+x.k,0),w0=c.w||(S.wt.length?S.wt[S.wt.length-1].kg:"");
 const opt=(i,cur,key)=>`<option value="${i}" ${cur==i?"selected":""}>${t(key)}</option>`;
 const tgt=r&&r.kc?r.kc:0,left=tgt?tgt-eaten:0;
 return `${langBar()}<div class="page">${backBtn("cclose")}<h1>${t("c_open")}</h1><p class="muted" style="margin:.3rem 0 1rem">${t("c_intro")}</p>
 <div class="card"><div class="gap"><label class="fl"><span>${t("c_age")}</span><input class="inp" id="c_age" inputmode="numeric" value="${c.age||""}"></label><label class="fl"><span>${t("c_sex")}</span><select class="inp" id="c_sex">${opt(0,c.sex,"c_m")}${opt(1,c.sex,"c_f")}</select></label></div><div class="sp2"></div>
 <div class="gap"><label class="fl"><span>${t("c_h")}</span><input class="inp" id="c_h" inputmode="numeric" value="${c.h||""}"></label><label class="fl"><span>${t("c_w")}</span><input class="inp" id="c_w" inputmode="decimal" value="${w0}"></label></div><div class="sp2"></div>
 <label class="fl"><span>${t("c_act")}</span><select class="inp" id="c_act">${opt(0,c.act,"a0")}${opt(1,c.act,"a1")}${opt(2,c.act,"a2")}</select></label><div class="sp"></div><button class="btn" data-a="ccalc">${t("c_calc")}</button></div>
 ${r?(r.young?`<div class="card" style="margin-top:.8rem"><p>${t("c_adult")}</p></div>`:`<div class="card" style="margin-top:.8rem"><h2 class="blue">${t("c_res",{n:r.kc})}</h2><p style="margin-top:.4rem">${t("c_prot",{a:r.pa,b:r.pb})}</p><p class="muted sm" style="margin-top:.4rem">${t("c_floor",{n:r.floor})}</p></div>`):""}
 <div class="sp"></div><div class="card"><h3>${t("c_how")}</h3><p class="muted sm" style="margin-top:.3rem">${t("c_how1")}<br>${t("c_how2")}<br>${t("c_how3")}</p></div>
 <div class="sp"></div><div class="card"><h3>${t("c_track")}</h3><div class="sp2"></div><div class="row"><div class="stat"><b>${eaten}</b><span class="muted sm">${t("c_eaten")}</span></div><div class="stat"><b>${tgt||"–"}</b><span class="muted sm">${t("c_target")}</span></div><div class="stat"><b class="${tgt&&left<0?"warnc":""}">${tgt?(left<0?t("c_over",{n:-left}):left):"–"}</b><span class="muted sm">${tgt&&left>=0?t("c_left"):""}</span></div></div>
 ${tgt?`<div class="bar" style="margin:.7rem 0"><i style="width:${Math.min(100,eaten/tgt*100)}%"></i></div>`:""}
 <p class="sm muted" style="margin-top:.6rem">${t("c_quick")}</p><div class="chips">${Object.keys(KC).map(k=>`<button class="chipb" data-a="cadd" data-v="${k}">${shortF(k)} · ${KC[k]}</button>`).join("")}</div>
 <div class="gap" style="margin-top:.8rem"><input class="inp" id="ckcal" inputmode="numeric" placeholder="${t("c_ph")}" style="flex:1"><button class="btn" data-a="cmanual" style="width:auto;padding:1rem 1.3rem">${t("c_add")}</button></div>
 ${log.map((x,i)=>`<div class="row" style="padding:.45rem 0;border-top:1px solid var(--line);margin-top:.4rem"><span>${x.n?shortF(x.n):t("c_ph")}</span><span><b>${x.k}</b> <button class="pill" data-a="cdel" data-v="${i}">✕</button></span></div>`).join("")}
 ${log.length?`<button class="btn sec" data-a="creset" style="margin-top:.8rem">${t("c_reset")}</button>`:""}<p class="muted sm" style="margin-top:.8rem">${t("c_approx")}</p></div></div>${nav()}`}

