function figBody(id,m){
 const P=POSES[id];if(!P)return"";const A=P.a[0],B=P.a[1],R=Math.PI/180;
 const mus=(INFO[id]&&INFO[id][0])||[];
 const glowOp=(0.35+0.55*m).toFixed(2);
 if(P.front){
  const a1=(A[0]+(B[0]-A[0])*m)*R,a2=(A[1]+(B[1]-A[1])*m)*R;
  const le=[84-Math.sin(a1)*20,50+Math.cos(a1)*20],lw=[le[0]-Math.sin(a2)*18,le[1]+Math.cos(a2)*18];
  const re=[116+Math.sin(a1)*20,50+Math.cos(a1)*20],rw=[re[0]+Math.sin(a2)*18,re[1]+Math.cos(a2)*18];
  return `<line x1="8" y1="118" x2="192" y2="118" stroke="#27405f" stroke-width="2" stroke-dasharray="5 5"/>`+
   `<path d="M62 66 Q58 44 74 34 M138 66 Q142 44 126 34" fill="none" stroke="rgba(255,255,255,${glowOp})" stroke-width="2" stroke-dasharray="3 3"/>`+
   `<polyline points="92,76 90,114" fill="none" stroke="#3b5bdb" stroke-width="12" stroke-linecap="round"/><polyline points="108,76 110,114" fill="none" stroke="#3b5bdb" stroke-width="12" stroke-linecap="round"/><rect x="84" y="44" width="32" height="36" rx="9" fill="#5DB8F5"/>`+
   `<polyline points="84,50 ${le[0].toFixed(1)},${le[1].toFixed(1)} ${lw[0].toFixed(1)},${lw[1].toFixed(1)}" fill="none" stroke="#F4B183" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/><polyline points="116,50 ${re[0].toFixed(1)},${re[1].toFixed(1)} ${rw[0].toFixed(1)},${rw[1].toFixed(1)}" fill="none" stroke="#F4B183" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/>`+
   `<circle cx="84" cy="49" r="${(6+2.5*m).toFixed(1)}" fill="rgba(255,59,31,${glowOp})"/><circle cx="116" cy="49" r="${(6+2.5*m).toFixed(1)}" fill="rgba(255,59,31,${glowOp})"/>`+
   `<circle cx="${lw[0].toFixed(1)}" cy="${lw[1].toFixed(1)}" r="5.5" fill="#cfd8e3"/><circle cx="${rw[0].toFixed(1)}" cy="${rw[1].toFixed(1)}" r="5.5" fill="#cfd8e3"/><circle cx="100" cy="30" r="10.5" fill="#F4B183"/>`;
 }
 const g=i=>{const x=A[i]===undefined?A[i-4]:A[i],y=B[i]===undefined?B[i-4]:B[i];return x+(y-x)*m};
 const T=g(0),Th=g(1),Sh=g(2),UA=g(3),FA=g(4),Th2=A[5]===undefined?Th:g(5),Sh2=A[6]===undefined?Sh:g(6);
 const K=P.k||.82,add=(q,a,l)=>[q[0]+Math.sin(a*R)*l*K,q[1]+Math.cos(a*R)*l*K];
 const hip=[0,0],sh=add(hip,T,38),hd=add(sh,T,15),k1=add(hip,Th,30),a1=add(k1,Sh,30),k2=add(hip,Th2,30),a2=add(k2,Sh2,30),el=add(sh,UA,23),wr=add(el,FA,21);
 const low=Math.max(a1[1]+3,a2[1]+3,wr[1]+3,k1[1]+5,k2[1]+5,hip[1]+8,sh[1]+8,hd[1]+10),dy=116-low,dx=P.x-a1[0];
 const q=pt=>(pt[0]+dx).toFixed(1)+","+(pt[1]+dy).toFixed(1),L=(pts,c,w)=>`<polyline points="${pts.map(q).join(" ")}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
 const foot=(a,c)=>L([a,[a[0]+10,a[1]+1]],c,7);
 const hq=q(hd).split(","),wq=q(wr).split(","),shq=q(sh).split(","),hipq=q(hip).split(",");
 const hiLeg=mus.some(k=>k==="th"||k==="ha"||k==="gl");
 const hiTorso=mus.some(k=>k==="ch"||k==="ba"||k==="be"||k==="lb");
 const hiArm=mus.some(k=>k==="bi"||k==="tr"||k==="sh");
 const auraLeg=hiLeg?L([hip,k1],`rgba(255,59,31,${glowOp})`,25):"";
 const auraTorso=hiTorso?L([hip,sh],`rgba(255,59,31,${glowOp})`,29):"";
 const auraArm=hiArm?L([sh,el,wr],`rgba(255,59,31,${glowOp})`,16):"";
 const auraSh=mus.includes("sh")?`<circle cx="${shq[0]}" cy="${shq[1]}" r="${(7+2.5*m).toFixed(1)}" fill="rgba(255,59,31,${glowOp})"/>`:"";
 const auraGl=mus.includes("gl")?`<circle cx="${hipq[0]}" cy="${hipq[1]}" r="${(8+2.5*m).toFixed(1)}" fill="rgba(255,59,31,${glowOp})"/>`:"";
 return `<line x1="8" y1="118" x2="192" y2="118" stroke="#27405f" stroke-width="2" stroke-dasharray="5 5"/>`+
  auraTorso+auraLeg+auraArm+
  L([hip,k2],"#A93A0C",15)+L([k2,a2],"#D99A6E",10)+foot(a2,"#cfd8e3")+
  L([hip,sh],hiTorso?"#ff5733":"#5DB8F5",22)+
  L([hip,k1],hiLeg?"#ff4d2d":"#D9480F",17)+L([k1,a1],"#F4B183",11)+foot(a1,"#ffffff")+
  L([sh,el],hiArm?"#ff6b4a":"#F4B183",10)+L([el,wr],"#F4B183",9)+
  auraSh+auraGl+
  (["row","gsquat","rdl","ohp","curl","tri","incline","pullover","lunge"].includes(id)?`<circle cx="${wq[0]}" cy="${wq[1]}" r="6" fill="#cfd8e3"/>`:"")+
  `<circle cx="${hq[0]}" cy="${hq[1]}" r="11" fill="#F4B183"/><circle cx="${(+hq[0]+4).toFixed(1)}" cy="${(+hq[1]-2).toFixed(1)}" r="1.7" fill="#14253D"/>`;
}
const figSvg=(id,cls)=>POSES[id]?`<svg class="fig ${cls||""}" data-ex="${id}" viewBox="0 0 200 130">${figBody(id,0)}</svg>`:"";
let AF=0,AL=0;const REDUCE=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;
function animLoop(ts){AF=requestAnimationFrame(animLoop);if(ts-AL<33)return;AL=ts;const els=document.querySelectorAll("svg.fig");if(!els.length){cancelAnimationFrame(AF);AF=0;return}
 els.forEach(e=>{const P=POSES[e.dataset.ex],per=(P?P.per:2.5)*1000,m=.5-.5*Math.cos(2*Math.PI*((ts%per)/per));e.innerHTML=figBody(e.dataset.ex,m)})}
